const item = $input.first().json;
const status = (item.status || '').toLowerCase();
// Polls are counted PER SCENE in static data, not with $runIndex — which
// counts every poll of the execution across all scenes, and a pass now
// covers the whole film (Sort & Cap Scenes resets sd.polls each pass).
// 30s a poll ('Wait Video'); 120 = one hour a clip, sized for the
// low-priority Veo queue. A clip that overruns it is treated as a FAILED
// job — 'Resubmit Guard' resubmits it — rather than killing the film.
const sd = $getWorkflowStaticData('global');
sd.polls = sd.polls || {};
const sceneId = $('Current Scene').first().json.id;
sd.polls[sceneId] = (sd.polls[sceneId] || 0) + 1;
const MAX_POLLS = 120;
const raw = JSON.stringify(item);
const done = status === 'completed' || raw.includes('flow-content.google/video');
let failed = status === 'failed' || status === 'error' || status === 'cancelled';
if (!done && !failed && sd.polls[sceneId] > MAX_POLLS) {
  console.log('Scene ' + sceneId + ': video job still not done after ' + MAX_POLLS + ' polls — treating as failed so it gets resubmitted.');
  failed = true;
  item.error = 'polling timed out after ' + MAX_POLLS + ' polls';
}
// Failed jobs are routed to a resubmit branch instead of throwing here —
// Google intermittently fails generations with VIDEO_GENERATION_TIMED_OUT
// and a resubmit usually succeeds.
return [{ json: Object.assign({}, item, { done: done && !failed, jobFailed: failed }) }];

const item = $input.first().json;
function find(obj, pred) {
  let f = null;
  (function w(o) { if (f) return;
    if (typeof o === 'string') { if (pred(o)) f = o; return; }
    if (Array.isArray(o)) { for (const v of o) { if (f) return; w(v); } return; }
    if (o && typeof o === 'object') { for (const k of Object.keys(o)) { if (f) return; w(o[k]); } }
  })(obj);
  return f;
}
let url = null, mediaId = null;
try { const gv = item.response && item.response.media && item.response.media[0] && item.response.media[0].video && item.response.media[0].video.generatedVideo; if (gv) { if (typeof gv.fifeUrl === 'string') url = gv.fifeUrl; if (typeof gv.mediaGenerationId === 'string') mediaId = gv.mediaGenerationId; } } catch (e) {}
if (!url) url = find(item, s => s.startsWith('http') && s.includes('flow-content.google') && s.includes('/video'));
if (!mediaId) mediaId = find(item, s => s.includes('-video:'));
if (!url && !mediaId) throw new Error('No video url or mediaId in completed job. Head: ' + JSON.stringify(item).slice(0, 800));
return [{ json: { Video_Signed_URL: url || '', Video_Media_Id: mediaId || '' } }];

const sd = $getWorkflowStaticData('global');
sd.prevImageUrl = '';
sd.prevImageId = '';
sd.anchorId = '';
// Every per-scene counter in this workflow lives here and is reset per
// pass: video polls / resubmits (batch loop), regen polls / resubmits (the
// gate), multi-voice polls, motion-prompt rewrites, submit cooldowns.
// They are keyed by scene id because $runIndex counts a node's runs across
// the WHOLE execution — and a pass now covers the whole film.
sd.polls = {};
sd.resubmits = {};
sd.regenPolls = {};
sd.regenResubmits = {};
sd.multiPolls = {};
sd.rewrites = {};
sd.submitCooldowns = {};
sd.imgRewrites = {};
sd.imgCooldowns = {};
sd.muxPolls = {};
const items = $input.all().slice();
const ord = it => { const f = it.json.fields || {}; return (typeof f['Ordine Scenă'] === 'number') ? f['Ordine Scenă'] : null; };
// "Done" is judged on the CLIP and the regen flags, never on the status
// text. It used to be the text ('Așteaptă Aprobare Video' / 'Finalizat'),
// and `VP Apply` stamped exactly that text on a scene whose clip had just
// been REFUSED by the video filter — so a refused scene sorted as finished,
// fell behind the cap on any film longer than 8 scenes, and was never
// generated again (Vegas, 71 scenes: 117, 118, 203 and 204 sat like that).
const pending = it => {
  const f = it.json.fields || {};
  const hasClip = String(f['Scene Final URL'] || '').startsWith('http');
  const flagged = f['Regenerează Video'] === true || f['Regenerează Imagine'] === true || f['Regenerează Voce'] === true;
  return !hasClip || flagged;
};
items.sort((a, b) => {
  const pa = pending(a), pb = pending(b);
  if (pa !== pb) return pa ? -1 : 1;
  const oa = ord(a), ob = ord(b);
  if (oa !== null && ob !== null && oa !== ob) return oa - ob;
  const t = new Date(a.json.createdTime) - new Date(b.json.createdTime);
  if (t) return t;
  return a.json.id < b.json.id ? -1 : 1;
});
if (!items.length) throw new Error('No approved scenes found for this project.');
// A pass covers the WHOLE film: every take, every image, one combined gate,
// every clip, one video gate. The cap was 8 until 2026-09-01, which turned a
// 71-scene film into nine rounds of approvals; the site mirrors this number
// in MEDIA_BATCH_CAP. 200 is a sanity bound (a 12-minute film is ~90
// scenes), not a chunk size. Pending-first sorting stays so a repeat pass
// (refused scenes, regen flags) still converges.
const CAP = 200;
if (items.length > CAP) {
  console.log('Sort & Cap: ' + items.length + ' approved scenes, running ' + CAP + '; ' + (items.length - CAP) + ' left for the next run.');
}
return items.slice(0, CAP);

const f = $json.fields || {};
const prompt = f['Imagine First Frame'] || f['Prompt Vizual'] || '';
if (!prompt) throw new Error('Scene ' + $json.id + ' has no image prompt.');
const rb = $('Receive Batch Input').first().json;
const aspect = rb.Aspect_Ratio === '9:16' ? '9:16' : '16:9';

// Images are generated ON Google Flow (useapi POST /google-flow/images):
// the response carries the signed fifeUrl the ingest re-hosts AND the
// mediaGenerationId Submit Video needs as startImage, so the picture is
// born past Flow's upload filter with its id already in hand. No fal, no
// download, no upload. One model string, here and in the gate's regen and
// Claude Scripting's IR Build Request — the three must agree.
const MODEL = 'nano-banana-2';

// The producer's reference photo, uploaded to Flow ONCE per film by the
// user-ref chain at pass start (Download User Ref -> Upload Asset To Flow ->
// Extract Asset Id -> Save User Ref Id) and stored as Editing Options
// .refImageMediaId. GROUND TRUTH for scene 1 (the hook): wins over the n-1
// chain and skips the similarity guard. IMG Load Project read the record
// BEFORE the id was saved on the pass that uploads it, so the fresh id is
// taken from Save User Ref Id when that node ran.
let userRefId = '';
try {
  const opts = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {};
  userRefId = String(opts.refImageMediaId || '');
} catch (e) {}
if (!userRefId) {
  try { if ($('Save User Ref Id').isExecuted) userRefId = String($('Save User Ref Id').first().json.media_id || ''); } catch (e) {}
}
const isFirstScene = Number(f['Ordine Scenă']) === 1;

// ---------------------------------------------------------------------------
// THE CAST SHEET — identity that does not have to travel through the film.
//
// Before this, the only thing carrying a face from scene to scene was the n-1
// chain: the previous scene's picture, handed over as "use this ONLY for
// character identity". That works while a film has one person in it, and it
// was measured working — the same man survives 71 scenes of the Boyd film.
// It cannot work for a CAST. The reference is whoever was in the last frame,
// so on a two-hander every scene tells the model to take Bill's identity from
// a picture of Sam, and a character who appears every fifth scene has no
// anchor at all. Names never reach the image model either (the segmenter's
// output-hygiene rule strips them), so the prose cannot disambiguate.
//
// A sheet is one portrait per character, generated once per film by the Cast
// Sheet chain and stored on the project as `castRefs` {name: mediaGenerationId}.
// Flow takes up to ten references, and we were using one.
//
// Who is in THIS scene is answered by `Prompt Vizual` — the segmenter's own
// visual_scene_description, which DOES name people ("Sam stands at the desk")
// and is stored per scene and never sent to any model. Measured on the Boyd
// film: Bill named in 27 scenes, Sam in 26, Crowley in 3, out of 71.
let castRefs = {};
try {
  castRefs = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}').castRefs || {};
} catch (e) { castRefs = {}; }
try {
  if ($('Save Cast Refs').isExecuted) {
    const fresh = $('Save Cast Refs').first().json.cast_refs;
    if (fresh && typeof fresh === 'object') castRefs = fresh;
  }
} catch (e) {}

let bibleChars = [];
try {
  bibleChars = JSON.parse((($('IMG Load Project').first().json.fields || {})['Story Bible']) || '{}').characters || [];
} catch (e) { bibleChars = []; }
if (!Array.isArray(bibleChars)) bibleChars = [];

const norm = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const sceneText = ' ' + norm(f['Prompt Vizual'] || '') + ' ';
// A shared surname is not an identifier: "Boyd" matches Sam, Bill and the
// company. Where the given name is unique it is enough, and it is what the
// description actually uses; where two characters share it, only the full
// name counts.
const givens = bibleChars.map((c) => norm(String((c || {}).name || '').split(/\s+/)[0] || ''));
const inScene = [];
for (const c of bibleChars) {
  const name = String((c || {}).name || '').trim();
  if (!name || !castRefs[name]) continue;
  const full = norm(name);
  const given = norm(name.split(/\s+/)[0] || '');
  const keys = givens.filter((g) => g && g === given).length > 1 ? [full] : [full, given];
  const hit = keys.some((k) => k.length > 2 && new RegExp('\\b' + esc(k) + '\\b').test(sceneText));
  if (hit) inScene.push({ name: name, id: castRefs[name] });
  // Two is the most a shot can be about. A third sheet crowds the references
  // and starts costing the composition.
  if (inScene.length >= 2) break;
}

// n-1 chain: the previous scene's generated image is the reference for
// this one, BY ITS FLOW MEDIA ID — no download, no upload. Read from the
// previous run of Decode Scene Image (run data survives Wait suspensions,
// unlike static data in test executions — proven in execution 661).
let prevId = '';
let prevPrompt = '';
try {
  if ($runIndex > 0) {
    const prev = $('Decode Scene Image').all(0, $runIndex - 1);
    if (prev && prev[0] && prev[0].json && prev[0].json.mediaId) prevId = prev[0].json.mediaId;
    const prevReq = $('Build Image Request').all(0, $runIndex - 1);
    if (prevReq && prevReq[0] && prevReq[0].json) prevPrompt = prevReq[0].json.rawPrompt || '';
  }
} catch (e) { prevId = ''; }

// Reference guard, unchanged: chaining exists for CHARACTER/wardrobe
// consistency. When consecutive prompts are largely the same words, text
// alone keeps the subject consistent — drop the reference so the composition
// can vary (the Porsche films collapsed into one repeated shot otherwise).
const wordSet = (s) => new Set(String(s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(w => w.length > 3));
let promptSim = 0;
if (prevPrompt) {
  const A = wordSet(prompt), B = wordSet(prevPrompt);
  if (A.size && B.size) {
    let hit = 0;
    for (const w of A) if (B.has(w)) hit++;
    promptSim = hit / Math.max(A.size, B.size);
  }
}
if (promptSim > 0.55) prevId = '';
// An in-place retry after a content refusal (the AUTO-REWRITE note is
// written by Apply Rewritten Prompt just before the scene re-enters the
// loop) gets NO reference image: the previous picture may carry exactly
// the content that was refused. Sheets go too — a face is the likeliest
// thing a people filter objected to.
const afterRefusal = /AUTO-REWRITE/.test(String(f['Observații Scenă'] || ''));
if (afterRefusal) prevId = '';

// count: 1 is mandatory — the API DEFAULTS TO FOUR images. captchaRetry: 1
// because useapi's five captcha retries per request are pure spend while
// Google throttles the account; our own cooldown loop handles that.
const body = { email: rb.Flow_Email || 'fermafabiz@gmail.com', model: MODEL, prompt: prompt, aspectRatio: aspect, count: 1, captchaRetry: 1 };
let usedReference = null;
let castUsed = [];
if (isFirstScene && userRefId) {
  body.prompt = 'The reference image is GROUND TRUTH for this film: recreate its subject faithfully — the same exact appearance, design details, materials, colors and overall look — while composing the shot described here: ' + prompt;
  body.reference_1 = userRefId;
  usedReference = userRefId;
} else if (!afterRefusal && inScene.length) {
  // Sheets first, the previous frame last: the order is what the sentence
  // below refers to, so it has to be built rather than assumed.
  const refs = inScene.map((p) => p.id);
  if (prevId && refs.length < 3) refs.push(prevId);
  const people = inScene.length === 1 ? 'reference image' : 'first ' + inScene.length + ' reference images';
  body.prompt =
    'The ' + people + ' define the EXACT appearance of the ' +
    (inScene.length === 1 ? 'person' : 'people') +
    ' in this shot — same face, same hair, same build, same wardrobe as shown. ' +
    (refs.length > inScene.length
      ? 'The LAST reference image is only for colour palette and film look, never for layout or for who anyone is. '
      : '') +
    'Compose the shot described here, which may place them at any distance, angle or part of the location: ' + prompt;
  refs.forEach((id, i) => { body['reference_' + (i + 1)] = id; });
  usedReference = refs[0];
  castUsed = inScene.map((p) => p.name);
} else if (prevId) {
  body.prompt = 'Use the reference image ONLY for character identity, wardrobe, color palette and film look — NOTHING else. The new shot must be a RADICALLY different composition: different camera angle, different distance, different part of the environment; the reference layout must NOT be recognizable in the result: ' + prompt;
  body.reference_1 = prevId;
  usedReference = prevId;
}
return [{ json: { sceneId: $json.id, requestBody: body, usedReference: usedReference, castUsed: castUsed, userRefApplied: !!(isFirstScene && userRefId), rawPrompt: prompt, promptSimilarityToPrev: Number(promptSim.toFixed(2)) } }];

// Flow answers synchronously: media[0].image.generatedImage carries the
// signed fifeUrl (expires — Write Scene Image's ingest downloads it on the
// spot and re-hosts the bytes) and the mediaGenerationId that Submit Video
// uses as startImage. Same shape Extract Video URL reads for clips.
const resp = $json;
const m0 = ((resp.media || [])[0] || {});
const gi = (m0.image && m0.image.generatedImage) || {};
const url = gi.fifeUrl || '';
const mediaId = gi.mediaGenerationId || '';
if (!url || !mediaId) throw new Error('No image in Flow response. Head: ' + JSON.stringify(resp).slice(0, 400));
const sceneId = $('Build Image Request').first().json.sceneId;
return [{ json: { sceneId: sceneId, url: url, mediaId: mediaId } }];

const expected = $('Sort & Cap Scenes').all().map(s => s.json.id);
const order = {};
expected.forEach((id, i) => order[id] = i);
const seen = new Set();
const recs = $input.all()
  .filter(r => order[r.json.id] !== undefined)
  .filter(r => { if (seen.has(r.json.id)) return false; seen.add(r.json.id); return true; })
  .slice()
  .sort((a, b) => order[a.json.id] - order[b.json.id]);
const regen = [];
recs.forEach((r, i) => {
  const f = r.json.fields || {};
  if (f['Regenerează Imagine'] === true) {
    // The previous scene's picture is the style reference, BY ITS FLOW MEDIA
    // ID: images are generated on Flow now, so a reference is a
    // mediaGenerationId (every scene made since the port carries a generated
    // one; older scenes carry the id of their upload). No download, no upload.
    const prevId = i > 0 ? String(((recs[i-1].json.fields || {})['Image Media ID']) || '') : '';
    // Reviewer feedback ("Observații Scenă", written from the site) steers
    // the regeneration instead of a blind re-roll.
    // …but only a HUMAN's note. The pipeline writes its own refusal notes
    // into the same field (AUTO-REWRITE / REJECTED …), and feeding those
    // back would put the refused content into the prompt a second time —
    // the trap CLAUDE.md describes under content filters.
    let feedback = String(f['Observații Scenă'] || '').trim();
    if (/^(AUTO-REWRITE|REJECTED|Image regeneration REJECTED)/i.test(feedback)) feedback = '';
    let prompt = f['Imagine First Frame'] || f['Prompt Vizual'] || '';
    if (feedback) prompt += '\n\nADJUSTMENT REQUEST — the new image MUST follow this: ' + feedback;
    regen.push({ id: r.json.id, prompt, prevId });
  }
});
const total = recs.length;
// This is the COMBINED asset gate. Takes and images are generated in one
// uninterrupted pass (audio loop first, image loop second) and reviewed
// together here, so the producer makes one visit instead of two before the
// expensive video stage. Voice regeneration is NOT dispatched from here —
// the standalone scene-voice-regen webhook covers it, exactly as it covered
// the old separate voice gate. Image regeneration keeps its in-batch chain
// (If Any Regen).
//
// A scene only counts as approved when its asset actually EXISTS — bulk
// approving before generation finished must not open the gate.
const imagesApproved = recs.filter(r => {
  const f = r.json.fields || {};
  const att = f['Imagine Scenă'];
  return f['Aprobare Imagine'] === true && Array.isArray(att) && att.length > 0;
}).length;
// Cinematic (silent) projects never synthesize: the pre-checked Aprobare
// Voce alone passes. AB Load Project runs whenever any scene lacked audio
// this pass; when it never ran (every scene already voiced) the catch
// leaves noSpeech false, which is correct for a project that has takes.
let noSpeech = false;
try { noSpeech = JSON.parse((($('AB Load Project').first().json.fields || {})['Editing Options']) || '{}').category === 'cinematic'; } catch (e) {}
const voicesApproved = recs.filter(r => {
  const f = r.json.fields || {};
  return f['Aprobare Voce'] === true && (noSpeech || String(f['Voiceover URL'] || '') !== '');
}).length;
const allApproved = total > 0 && imagesApproved === total && voicesApproved === total;
return [{ json: { anyRegen: regen.length > 0, allApproved, regen, total, approved: imagesApproved, imagesApproved, voicesApproved } }];

const inputs = $('Split Regen List').all();
const resps = $input.all();
if (resps.length !== inputs.length) throw new Error('Regen response count (' + resps.length + ') != request count (' + inputs.length + ')');
return resps.map((r, i) => {
  // Flow answers synchronously — see Decode Scene Image for the shape.
  const m0 = (((r.json || {}).media || [])[0] || {});
  const gi = (m0.image && m0.image.generatedImage) || {};
  if (!gi.fifeUrl || !gi.mediaGenerationId) throw new Error('No image on regen (Google Flow) for scene ' + inputs[i].json.id + '. Payload head: ' + JSON.stringify(r.json).slice(0, 300));
  return { json: { sceneId: inputs[i].json.id, url: gi.fifeUrl, mediaId: gi.mediaGenerationId } };
});

const expected = $('Sort & Cap Scenes').all().map(s => s.json.id);
const order = {};
expected.forEach((id, i) => order[id] = i);
const seen = new Set();
const recs = $input.all()
  .filter(r => order[r.json.id] !== undefined)
  .filter(r => { if (seen.has(r.json.id)) return false; seen.add(r.json.id); return true; })
  .slice()
  .sort((a, b) => order[a.json.id] - order[b.json.id]);
const missing = recs.filter(r => { const a = (r.json.fields || {})['Imagine Scenă']; return !(Array.isArray(a) && a[0] && a[0].url); });
if (missing.length) throw new Error('Scenes missing approved image: ' + missing.map(r => r.json.id).join(', '));
return recs;

// The scene, unchanged, plus the video request built for it.
//
// Built HERE because three edges reach Submit Video — the first submit, the
// resubmit guard and the cooldown retry — and all three read
// $('Current Scene'), so deciding once per scene keeps them agreeing and
// needs no rewiring.
const f = $json.fields || {};
const rb = $('Receive Batch Input').first().json;

let opts = {};
try { opts = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {}; } catch (e) { opts = {}; }

// FREE BY DEFAULT, and that is the business model rather than a saving.
// veo-3.1-lite-low-priority costs 0 credits on Ultra $199 at any volume. At
// three films a day of eighty scenes — 7,200 clips a month — the same work on
// Fast would be 72,000 credits against an allowance of 25,050, so no paid
// tier can be the default at this scale. Credits buy the exceptions.
const FREE = 'veo-3.1-lite-low-priority';
const PAID = 'veo-3.1-quality';
const base = String(opts.videoModel || FREE);

// How many takes of this shot already exist. `Versiuni Media` is the draft
// list the site keeps, and every regeneration files the outgoing clip there,
// so its length is the number of times this shot has already been tried.
// at_scene emits it as TEXT, hence the parse.
let takes = 0;
try {
  const v = f['Versiuni Media'];
  const list = Array.isArray(v) ? v : JSON.parse(String(v || '[]'));
  takes = list.filter((e) => e && e.kind === 'video').length;
} catch (e) { takes = 0; }

// The HOOK is the one clip that decides whether the film is watched at all,
// and there is exactly one per film — the only per-film cost that does not
// grow with the number of scenes. Switchable: hookVideoModel.
const isHook = Number(f['Ordine Scenă']) === 1;
const hookModel = opts.hookVideoModel === undefined ? PAID : String(opts.hookVideoModel);
let model = base;
let why = 'default';
if (base === FREE && isHook && hookModel && hookModel !== FREE) { model = hookModel; why = 'hook'; }

// A seed makes a re-roll a DIFFERENT take rather than another coin flip, and
// makes a first take reproducible. Derived from the scene id and the number
// of takes already filed, so nothing has to be stored anywhere.
const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
const seed = hash(String($json.id || '') + ':' + takes) % 2147483647;

// count is deliberately 1. Two takes per submission is free on the
// low-priority tier, but at three films a day the scarce resource is QUEUE
// TIME, not credits: asking for a second take of every scene halves the
// throughput ceiling to save a click on the tenth of scenes that need it.
// Turning it on also needs somewhere for take B to live — a Flow URL dies in
// about six hours, so it would have to go through the same Drive re-host the
// live clip does before the site could file it as a draft.
console.log('VIDEO ' + f['Ordine Scenă'] + ': ' + model + ' (' + why + '), seed ' + seed + ', ' + takes + ' previous take(s)');

return [{ json: Object.assign({}, $json, { videoRequest: {
  email: rb.Flow_Email || 'fermafabiz@gmail.com',
  model: model,
  prompt: String(f['Video Scenă URL'] || '') + ' Continuity: everything that moves travels the same way as the subject — no oncoming vehicles, nobody walking or driving against the flow, no reversed motion, and no subject that appears, disappears or duplicates. Physics: solid things stay solid — vehicles, people and objects never pass through each other, never overlap and never sink into the ground; every moving vehicle has its driver (visible, or plausibly hidden by the bodywork); nothing floats, melts or morphs. Audio: quiet natural ambient sound effects that match the scene only — no speech, no voices, no singing, no narration, no music, no soundtrack.',
  startImage: f['Image Media ID'],
  aspectRatio: (rb.Aspect_Ratio === '9:16' ? 'portrait' : 'landscape'),
  seed: seed,
  count: 1,
  async: true,
  captchaRetry: 1,
} }) }];

const j = $input.first().json;
const s = (j.status || '').toLowerCase();
if (s === 'error') throw new Error('scene mux failed: ' + (j.error || 'unknown'));
if ($runIndex > 30) throw new Error('scene mux timed out after ' + $runIndex + ' polls. Last status: ' + s);
return [{ json: j }];

const item = $json;
let id = '';
const raw = item.mediaGenerationId;
if (typeof raw === 'string') id = raw;
else if (raw && typeof raw.mediaGenerationId === 'string') id = raw.mediaGenerationId;
if (!id) {
  (function walk(o) {
    if (id) return;
    if (typeof o === 'string') { if (o.includes('-image:') || o.includes('-asset:')) id = o; return; }
    if (Array.isArray(o)) { for (const v of o) { if (id) return; walk(v); } return; }
    if (o && typeof o === 'object') { for (const k of Object.keys(o)) { if (id) return; walk(o[k]); } }
  })(item);
}
if (!id || typeof id !== 'string') throw new Error('No mediaGenerationId string found in Flow asset upload response: ' + JSON.stringify(item).slice(0, 500));
return [{ json: { mediaId: id } }];

const expected = $('Sort & Cap Scenes').all().map(s => s.json.id);
const order = {};
expected.forEach((id, i) => order[id] = i);
const seen = new Set();
const recs = $input.all()
  .filter(r => order[r.json.id] !== undefined)
  .filter(r => { if (seen.has(r.json.id)) return false; seen.add(r.json.id); return true; })
  .slice()
  .sort((a, b) => order[a.json.id] - order[b.json.id]);
// One regen per polling cycle: keeps the submit->poll->mux chain simple and
// avoids splitInBatches re-entry problems. Remaining flags are picked up on
// the next 15s cycle automatically.
let regen = null;
for (const r of recs) {
  const f = r.json.fields || {};
  if (f['Regenerează Video'] === true) {
    const feedback = String(f['Observații Scenă'] || '').trim();
    let motionPrompt = f['Video Scenă URL'] || '';
    if (feedback) motionPrompt += ' ADJUSTMENT REQUEST — the new video MUST follow this: ' + feedback + '.';
    regen = { id: r.json.id, motionPrompt, imageId: f['Image Media ID'] || '', voiceUrl: f['Voiceover URL'] || '' };
    break;
  }
}
// Voice-only regeneration (site button): new TTS from the (possibly edited)
// narration, re-muxed onto the EXISTING clip — no image/video redo.
let voiceRegen = null;
for (const r of recs) {
  const f = r.json.fields || {};
  if (f['Regenerează Voce'] === true) {
    voiceRegen = {
      id: r.json.id,
      text: String(f['Script Scenă'] || '').trim(),
      clipUrl: String(f['Scene Final URL'] || ''),
    };
    break;
  }
}
const total = recs.length;
// A scene only counts as approved if its muxed clip actually exists —
// bulk-approving before generation finished must not open the gate.
const approved = recs.filter(r => { const f = r.json.fields || {}; return f['Aprobare Video'] === true && String(f['Scene Final URL'] || '').startsWith('http'); }).length;
return [{ json: { anyRegen: !!regen, anyVoiceRegen: !!voiceRegen, allApproved: total > 0 && approved === total, regen, voiceRegen, total, approved } }];

const r = $json.regen;
if (!r) throw new Error('No regen payload.');
if (!r.imageId) throw new Error('Scene ' + r.id + ' has no Image Media ID — cannot regenerate its video (regenerate/approve its image first).');
if (!r.motionPrompt) throw new Error('Scene ' + r.id + ' has no motion prompt (Video Scenă URL).');

// Which model this re-roll deserves. Same rule as Current Scene, and the two
// must keep agreeing — a rescued clip that obeys a different rule from its
// neighbours is a new inconsistency.
//
// This is where the rescue actually fires: the main path only submits scenes
// with NO clip at all, so a scene on its third attempt can only arrive here.
let opts = {};
try { opts = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {}; } catch (e) { opts = {}; }
const FREE = 'veo-3.1-lite-low-priority';
const PAID = 'veo-3.1-quality';
const base = String(opts.videoModel || FREE);

// Takes already filed for this shot, read from the scene the gate fetched.
let takes = 0;
try {
  const row = $('Fetch Scene Videos').all().find((x) => x.json && x.json.id === r.id);
  const v = row ? ((row.json.fields || {})['Versiuni Media']) : null;
  const list = Array.isArray(v) ? v : JSON.parse(String(v || '[]'));
  takes = list.filter((e) => e && e.kind === 'video').length;
} catch (e) { takes = 0; }

// Two free takes the producer has already refused is the evidence that this
// shot is not something the free tier can do. Everything before that is a
// coin flip worth re-flipping for nothing.
const rescue = opts.rescueVideoModel === undefined ? PAID : String(opts.rescueVideoModel);
const model = (base === FREE && takes >= 2 && rescue && rescue !== FREE) ? rescue : base;
const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
const seed = hash(String(r.id || '') + ':' + takes) % 2147483647;
console.log('VIDEO REGEN ' + r.id + ': ' + model + (model === base ? '' : ' (rescue after ' + takes + ' takes)') + ', seed ' + seed);

return [{ json: Object.assign({}, r, { model: model, seed: seed, takes: takes }) }];

const item = $input.first().json;
const status = (item.status || '').toLowerCase();
// Per scene in static data (reset by Sort & Cap each pass), 30s a poll
// ('Wait Video Regen'); 120 = one hour a clip on the low-priority queue.
// Overrunning it counts as a failed job and goes through 'Regen Resubmit
// Guard' — same rule as 'Check Job Status'.
const sd = $getWorkflowStaticData('global');
sd.regenPolls = sd.regenPolls || {};
const sceneId = $('Prep Video Regen').first().json.id;
sd.regenPolls[sceneId] = (sd.regenPolls[sceneId] || 0) + 1;
const MAX_POLLS = 120;
const raw = JSON.stringify(item);
const done = status === 'completed' || raw.includes('flow-content.google/video');
let failed = status === 'failed' || status === 'error' || status === 'cancelled';
if (!done && !failed && sd.regenPolls[sceneId] > MAX_POLLS) {
  console.log('Scene ' + sceneId + ': video regen still not done after ' + MAX_POLLS + ' polls — treating as failed so it gets resubmitted.');
  failed = true;
  item.error = 'polling timed out after ' + MAX_POLLS + ' polls';
}
return [{ json: Object.assign({}, item, { done: done && !failed, jobFailed: failed }) }];

const item = $input.first().json;
function find(obj, pred) {
  let f = null;
  (function w(o) { if (f) return;
    if (typeof o === 'string') { if (pred(o)) f = o; return; }
    if (Array.isArray(o)) { for (const v of o) { if (f) return; w(v); } return; }
    if (o && typeof o === 'object') { for (const k of Object.keys(o)) { if (f) return; w(o[k]); } }
  })(obj);
  return f;
}
let url = null;
let mediaId = null;
try { const gv = item.response && item.response.media && item.response.media[0] && item.response.media[0].video && item.response.media[0].video.generatedVideo; if (gv) { if (typeof gv.fifeUrl === 'string') url = gv.fifeUrl; if (typeof gv.mediaGenerationId === 'string') mediaId = gv.mediaGenerationId; } } catch (e) {}
if (!url) url = find(item, s => s.startsWith('http') && s.includes('flow-content.google') && s.includes('/video'));
// The clip's own Flow identity, which POST /videos/upscale needs later. The
// main extractor has always pulled it; this one did not, so a regenerated
// clip would have been the one clip in a film that could never be upscaled.
if (!mediaId) mediaId = find(item, s => s.includes('-video:'));
if (!url) throw new Error('No video url in regen job. Head: ' + JSON.stringify(item).slice(0, 800));
return [{ json: { Video_Signed_URL: url, Video_Media_Id: mediaId || '' } }];

const j = $input.first().json;
const s = (j.status || '').toLowerCase();
if (s === 'error') throw new Error('regen mux failed: ' + (j.error || 'unknown'));
if ($runIndex > 30) throw new Error('regen mux timed out after ' + $runIndex + ' polls. Last status: ' + s);
return [{ json: j }];

// Cap video resubmits PER SCENE (static data, reset by Sort & Cap each pass)
// so a persistent Google failure can't loop forever. Used to be $runIndex,
// i.e. five resubmits for the whole execution — far too few now that a pass
// covers the whole film.
const sd = $getWorkflowStaticData('global');
sd.resubmits = sd.resubmits || {};
sd.polls = sd.polls || {};
const sceneId = $('Current Scene').first().json.id;
const n = (sd.resubmits[sceneId] || 0) + 1;
sd.resubmits[sceneId] = n;
const MAX = 5;
if (n > MAX) {
  const err = ($json.error || $json.status || 'unknown');
  throw new Error('Scene ' + sceneId + ': too many failed video generations (' + n + '). Last job status/error: ' + String(err).slice(0, 200));
}
sd.polls[sceneId] = 0;
console.log('Scene ' + sceneId + ': resubmitting video (' + n + '/' + MAX + ').');
return [{ json: { resubmit: true, attempt: n } }];

// Per scene (static data, reset by Sort & Cap each pass) — $runIndex would
// count every regeneration of the execution together.
const sd = $getWorkflowStaticData('global');
sd.regenResubmits = sd.regenResubmits || {};
sd.regenPolls = sd.regenPolls || {};
const payload = $('Prep Video Regen').first().json;
const n = (sd.regenResubmits[payload.id] || 0) + 1;
sd.regenResubmits[payload.id] = n;
const MAX = 4;
if (n > MAX) throw new Error('Scene ' + payload.id + ': too many failed video regenerations in this run (' + n + ').');
sd.regenPolls[payload.id] = 0;
// Re-feed the regen payload so Submit Video Regen gets motionPrompt/imageId again.
return [{ json: payload }];

// All videos approved: emit one item per scene so the next Airtable node
// marks each record Finalizat. Dedupe — Fetch Scene Videos can return
// duplicates when the poll loop ran multiple times.
const seen = new Set();
const out = [];
for (const r of $('Fetch Scene Videos').all()) {
  const id = r.json.id;
  if (!id || seen.has(id)) continue;
  seen.add(id);
  out.push({ json: { id } });
}
return out;

const r = $json.voiceRegen;
if (!r) throw new Error('No voice regen payload.');
if (!r.text) throw new Error('Scene ' + r.id + ' has no narration text (Script Scenă).');
// No clip is needed: the picture is never re-muxed. Final assembly mixes
// whatever voiceover the scene holds at render time.
return [{ json: r }];

const j = $input.first().json;
const s = (j.status || '').toLowerCase();
if (s === 'error') throw new Error('voice-regen mux failed: ' + (j.error || 'unknown'));
if ($runIndex > 30) throw new Error('voice-regen mux timed out after ' + $runIndex + ' polls. Last status: ' + s);
return [{ json: j }];

// ONE item per scene, in film order. 'Refetch Scenes For Audio' used to run
// once per input item — N scenes in, N queries out, each returning all N
// scenes — so this node received N copies of every scene, Loop Audio
// walked every copy, and AB Speak synthesized each line N times (billed N
// times, N Drive uploads, the last write winning). 8x since the audio-first
// reorder of 2026-08-26; 71x on the Vegas film, where one line cost eight
// minutes. Refetch is executeOnce now; the dedupe stays as a second lock,
// exactly as 'Sort Scenes For Video' has always had one.
const seen = new Set();
const items = $input.all().filter(it => {
  const id = it.json.id;
  if (!id || seen.has(id)) return false;
  seen.add(id);
  return true;
});
const ord = (it) => { const f = it.json.fields || {}; return (typeof f['Ordine Scenă'] === 'number') ? f['Ordine Scenă'] : null; };
items.sort((a, b) => {
  const oa = ord(a), ob = ord(b);
  if (oa !== null && ob !== null && oa !== ob) return oa - ob;
  const t = new Date(a.json.createdTime) - new Date(b.json.createdTime);
  if (t) return t;
  return a.json.id < b.json.id ? -1 : 1;
});
return items;

// Collapse the per-scene items into one: the gate below is about the
// project, not about each scene.
const pid = $('Fetch Approved Scenes').first().json.fields.Project_ID;
if (!pid) throw new Error('Project_ID missing on the scenes.');
return [{ json: { projectId: Array.isArray(pid) ? pid[0] : pid } }];

// The user confirms the overlay options on the site, which flips the
// project status off 'Setări Finale'. Release on ANY move away from the
// waiting state, not on one specific value: starting the render from the
// site's Restart button takes the project straight to 'Finalizat', so a
// test for 'Asamblare' alone would sit here for the full timeout while the
// video was already rendered. Don't hold an execution open forever if
// nobody confirms either: after ~2h assume the defaults and assemble.
//
// The project record comes from 'Fetch Final Settings' BY NAME, because the
// input of this node is now the scene list from 'Fetch Regen Flags'.
const proj = $('Fetch Final Settings').first().json.fields || {};
const status = String(proj['Status General'] || '');
const WAITING = 'Setări Finale';
const timedOut = $runIndex > 480;
const moved = status !== '' && status !== WAITING;

// Video regeneration is the ONLY regeneration with no webhook of its own —
// it is seen solely by 'Evaluate Video Approval', inside the video stage.
// So a scene flagged after the batch walked past that gate had nobody left
// to clear it: the flag sat forever (130 stranded base-wide when this was
// written) and the site showed a 'Regenerating…' badge that never resolved.
// While waiting here we watch for the flag and send the run back for
// another pass — the flagged scene carries 'Generare Video', so
// 'Sort & Cap Scenes' sorts it as outstanding work and it lands in the cap.
//
// ONE automatic bounce per scene per execution. If a pass does not clear
// the flag, bouncing again would only ping-pong between the two gates; the
// site has its own local exit for that scene (restartVideoRegen /
// cancelVideoRegen).
const flagged = $input.all()
  .filter(r => ((r.json.fields || {})['Regenerează Video'] === true))
  .map(r => r.json.id)
  .filter(Boolean);

const sd = $getWorkflowStaticData('global');
const key = 'sgBounced_' + $execution.id;
// Per-execution note, not a store: keep the map from growing without bound.
const old = Object.keys(sd).filter(k => k.startsWith('sgBounced_') && k !== key);
if (old.length > 10) old.slice(0, old.length - 10).forEach(k => delete sd[k]);
const bounced = new Set(sd[key] || []);
const fresh = flagged.filter(id => !bounced.has(id));
const regenPending = !moved && !timedOut && fresh.length > 0;
if (regenPending) {
  fresh.forEach(id => bounced.add(id));
  sd[key] = Array.from(bounced);
  console.log('Settings gate: ' + fresh.length + ' scene(s) flagged for video regeneration — going back for another pass: ' + fresh.join(', '));
} else if (flagged.length && !moved) {
  console.log('Settings gate: ' + flagged.length + ' scene(s) still flagged for video regeneration, already retried this run — holding at the gate.');
}

return [{ json: { status, confirmed: moved || timedOut, timedOut, regenPending, flagged: flagged.length } }];

// Which voice (or voices) read this scene.
// - 'chapters': the chapter's narrator — an explicit pick from the audio
//   panel, else cast[N-1] (looping); the hook keeps the main narrator
//   unless it was given a voice of its own.
// - 'characters': the scene text carries [NARRATOR]/[CHARACTER: Name] tags;
//   it is split into segments, each with its speaker's voice. Characters
//   are assigned voices by explicit castAssign (set in the audio panel) or,
//   failing that, by first appearance across the whole project — the same
//   deterministic rule the site shows.
// - anything else: the project narrator, exactly the pre-multi-voice logic.
const rb = $('Receive Batch Input').first().json;
const fallback = ((rb.Voice_ID || '').includes('_')) ? rb.Voice_ID : 'elevenlabs_hpp4J3VqNfWAUOO0d1Us';
let voice = fallback, mode = 'off', cast = [], assign = {}, chapterVoices = {};
try {
  const pf = $('AB Load Project').first().json.fields || {};
  const opts = JSON.parse(pf['Editing Options'] || '{}') || {};
  mode = String(opts.multiVoiceMode || 'off');
  cast = (Array.isArray(opts.cast) ? opts.cast : []).filter(v => typeof v === 'string' && v.includes('_'));
  assign = (opts.castAssign && typeof opts.castAssign === 'object') ? opts.castAssign : {};
  // Explicit per-chapter narrators picked in the audio panel; the key is
  // the chapter number as a string, plus 'hook' for the opening scene.
  chapterVoices = (opts.chapterVoices && typeof opts.chapterVoices === 'object') ? opts.chapterVoices : {};
} catch (e) {}
const f = $('AB Current Scene').first().json.fields || {};
const text = String(f['Script Scenă'] || '');
if (mode === 'chapters' && (cast.length || Object.keys(chapterVoices).length)) {
  const o = Number(f['Ordine Scenă']);
  const chapter = Number.isFinite(o) ? Math.floor(o / 100) : 0;
  // An explicit pick always wins — including for the hook, which has
  // no position in the cast and otherwise keeps the main narrator.
  const picked = chapterVoices[chapter > 0 ? String(chapter) : 'hook'];
  if (typeof picked === 'string' && picked.includes('_')) voice = picked;
  else if (chapter > 0 && cast.length) voice = cast[(chapter - 1) % cast.length];
}
let multi = false, segments = [];
if (mode === 'characters' && cast.length) {
  const all = $('Refetch Scenes For Audio').all().map(s => s.json)
    .sort((a, b) => (Number((a.fields || {})['Ordine Scenă']) || 0) - (Number((b.fields || {})['Ordine Scenă']) || 0));
  const order = [];
  for (const sc of all) {
    const t = String((sc.fields || {})['Script Scenă'] || '');
    for (const m of t.matchAll(/\[\s*CHARACTER:\s*([^\]]+)\]/gi)) {
      const n = m[1].trim();
      if (n && !order.includes(n)) order.push(n);
    }
  }
  const voiceFor = (name) => {
    const a = assign[name];
    if (typeof a === 'string' && a.includes('_')) return a;
    const i = order.indexOf(name);
    return cast[(i >= 0 ? i : 0) % cast.length];
  };
  let cur = fallback;
  for (const tk of text.split(/(\[[^\[\]]{1,60}\])/)) {
    if (/^\[\s*NARRATOR\s*\]$/i.test(tk)) { cur = fallback; continue; }
    const cm = tk.match(/^\[\s*CHARACTER:\s*([^\]]+)\]$/i);
    if (cm) { cur = voiceFor(cm[1].trim()); continue; }
    const t = tk.replace(/\s+/g, ' ').trim();
    if (!t) continue;
    const last = segments[segments.length - 1];
    if (last && last.voice_id === cur) last.text += ' ' + t;
    else segments.push({ text: t, voice_id: cur });
  }
  // Only worth the multi pipeline when a second voice actually appears.
  multi = segments.length > 0 && segments.some(s => s.voice_id !== fallback);
}
return [{ json: { voice_id: voice, multi, segments } }];

const j = $input.first().json;
const s = (j.status || '').toLowerCase();
if (s === 'error') throw new Error('multi-voice TTS failed: ' + (j.error || 'unknown'));
// Per scene in static data (reset by Sort & Cap each pass) — $runIndex
// would count every scene's polls together, and a pass covers the film.
const sd = $getWorkflowStaticData('global');
sd.multiPolls = sd.multiPolls || {};
const sceneId = $('AB Current Scene').first().json.id;
sd.multiPolls[sceneId] = (sd.multiPolls[sceneId] || 0) + 1;
if (sd.multiPolls[sceneId] > 40) throw new Error('multi-voice TTS timed out after ' + sd.multiPolls[sceneId] + ' polls on scene ' + sceneId + '. Last status: ' + s);
return [{ json: j }];

// Context for the auto-rewrite: the scene, the prompt that was ACTUALLY
// sent, and WHY the image was refused.
//
// Images are generated ON Google Flow (since 2026-09-02), so a refusal is
// Flow's own content filter at GENERATION time — no image was made. The
// upload-time refusals this chain was first built for (MINOR / prominent
// people at Upload Asset To Flow) can now only come from the producer's
// reference photo, which is uploaded once per pass and never lands here.
// Either way the cure is the same: rewrite the prompt, never resubmit the
// refused text. The scene id and note are read from Loop Images rather
// than from the error, which is what lets one chain serve every entry.
//
// The rewrite is retried IN PLACE (Apply Rewritten Prompt → IMG Reload
// Scene → Needs Image?), so this node runs once per attempt for the same
// scene. Attempts are counted per scene per pass in static data (Sort & Cap
// resets sd.imgRewrites); after MAX the scene is handed to a human.
const scene = $('Loop Images').first().json || {};
const f = scene.fields || {};
const errText = JSON.stringify($json).slice(0, 1500);
const service = 'Google Flow';
let reason = service + ' content policy';
if (errText.includes('MINOR')) reason = 'the image appears to contain a child (Flow refuses images with minors)';
else if (errText.includes('PROMINENT') || errText.includes('FACE')) reason = 'the image appears to contain a recognizable real person';
// After an in-place rewrite the Loop Images item still holds the ORIGINAL
// text; the prompt that was sent is Build Image Request's latest run.
let prompt = '';
try { prompt = String($('Build Image Request').first().json.rawPrompt || ''); } catch (e) {}
if (!prompt) prompt = String(f['Imagine First Frame'] || '');
const note = String(f['Observații Scenă'] || '');
const sd = $getWorkflowStaticData('global');
sd.imgRewrites = sd.imgRewrites || {};
const n = (sd.imgRewrites[scene.id] || 0) + 1;
sd.imgRewrites[scene.id] = n;
const MAX = 4;
// A scene that arrives already carrying a refusal note from an earlier pass
// starts one rung further up the escalation ladder.
const attempt = n + (/AUTO-REWRITE|REJECTED/.test(note) ? 1 : 0);
console.log('Image refused for ' + scene.id + ' by ' + service + ' (attempt ' + n + '/' + MAX + ')');
return [{ json: {
  sceneId: scene.id,
  prompt,
  note,
  service,
  reason,
  attempt,
  giveUp: n > MAX,
} }];

parameters.jsonBody:
={{ { model: 'gpt-4o-mini', temperature: 0.4, messages: [ { role: 'system', content: 'You rewrite image-generation prompts that were refused by a content filter. Keep the scene's story intent, location, lighting, palette, lens and mood EXACTLY; change only what triggers the refusal. If the reason involves a child/minor: replace the child with an adult, OR keep the child implied but strictly off-screen (a small shoe, a toy, a shadow under a door, an empty swing) — no minor may be visible. If it involves a real/recognizable person: make the person generic and unrecognizable.' + ($json.attempt >= 2 ? ' THIS IS REWRITE ATTEMPT ' + $json.attempt + ': earlier rewrites of this prompt were STILL refused, so go much further. Remove every explicit depiction of violence, blood, injury, weapons, drugs, self-harm, nudity or sexual content; no children or teenagers anywhere; no real or named people, no brands or logos; every person generic, adult, fully clothed and calm; keep the faces of people out of frame (from behind, in silhouette, at a distance, or hands and objects only) and show the situation through objects, environment, light and weather.' : '') + ($json.attempt >= 3 ? ' Remove every person from the frame entirely: an empty environment whose objects, light and weather carry the mood.' : '') + ' Return ONLY the rewritten prompt text, no commentary.' }, { role: 'user', content: 'Refusal reason: ' + $json.reason + '

Original prompt:
' + $json.prompt } ] } }}

parameters.jsCode:
// The video filter refused this scene's clip. Count the rewrite PER SCENE
// (static data, reset by Sort & Cap each pass): the prompt is rewritten and
// the SAME scene resubmitted in place, up to MAX_REWRITES times, each
// rewrite more conservative than the last. Only after that does the scene
// get marked rejected and the loop move on — by then the trigger is almost
// certainly the start image, which no prompt can fix (see CLAUDE.md,
// "Content filters").
const sd = $getWorkflowStaticData('global');
sd.rewrites = sd.rewrites || {};
const cur = $('Current Scene').first().json || {};
const f = cur.fields || {};
const sceneId = cur.id;
const n = (sd.rewrites[sceneId] || 0) + 1;
sd.rewrites[sceneId] = n;
const MAX_REWRITES = 4;
const errText = JSON.stringify($json).slice(0, 2000);
let reason = 'Google video content filter';
if (errText.includes('PROMINENT')) reason = 'the motion prompt names or depicts a recognizable real person';
else if (errText.includes('MINOR')) reason = 'the motion prompt places a child on screen';
console.log('Scene ' + sceneId + ': video filter refusal (' + reason + '), rewrite ' + n + '/' + MAX_REWRITES + (n > MAX_REWRITES ? ' — giving up' : ''));
return [{ json: {
  sceneId,
  prompt: String(f['Video Scenă URL'] || ''),
  note: String(f['Observații Scenă'] || ''),
  reason,
  attempt: n,
  giveUp: n > MAX_REWRITES,
} }];

