  cast = (Array.isArray(opts.cast) ? opts.cast : []).filter(v => typeof v === 'string' && v.includes('_'));
  assign = (opts.castAssign && typeof opts.castAssign === 'object') ? opts.castAssign : {};
  // Explicit per-chapter narrators picked in the audio panel; the key is
  // the chapter number as a string, plus 'hook' for the opening scene.
  chapterVoices = (opts.chapterVoices && typeof opts.chapterVoices === 'object') ? opts.chapterVoices : {};
} catch (e) {}
const f = $('AB Current Scene').first().json.fields || {};
const text = String(f['Script Scenă'] || '');
if (mode === 'chapters' && (cast.length || Object.keys(chapterVoices).length)) {
  const o = Number(f['Ordine Scenă']);
  const chapter = Number.isFinite(o) ? Math.floor(o / 100) : 0;
  // An explicit pick always wins — including for the hook, which has
  // no position in the cast and otherwise keeps the main narrator.
  const picked = chapterVoices[chapter > 0 ? String(chapter) : 'hook'];
  if (typeof picked === 'string' && picked.includes('_')) voice = picked;
  else if (chapter > 0 && cast.length) voice = cast[(chapter - 1) % cast.length];
}
let multi = false, segments = [];
if (mode === 'characters' && cast.length) {
  const all = $('Refetch Scenes For Audio').all().map(s => s.json)
    .sort((a, b) => (Number((a.fields || {})['Ordine Scenă']) || 0) - (Number((b.fields || {})['Ordine Scenă']) || 0));
  const order = [];
  for (const sc of all) {
    const t = String((sc.fields || {})['Script Scenă'] || '');
    for (const m of t.matchAll(/\[\s*CHARACTER:\s*([^\]]+)\]/gi)) {
      const n = m[1].trim();
      if (n && !order.includes(n)) order.push(n);
    }
  }
  const voiceFor = (name) => {
    const a = assign[name];
    if (typeof a === 'string' && a.includes('_')) return a;
    const i = order.indexOf(name);
    return cast[(i >= 0 ? i : 0) % cast.length];
  };
  let cur = fallback;
  for (const tk of text.split(/(\[[^\[\]]{1,60}\])/)) {
    if (/^\[\s*NARRATOR\s*\]$/i.test(tk)) { cur = fallback; continue; }
    const cm = tk.match(/^\[\s*CHARACTER:\s*([^\]]+)\]$/i);
    if (cm) { cur = voiceFor(cm[1].trim()); continue; }
    const t = tk.replace(/\s+/g, ' ').trim();
    if (!t) continue;
    const last = segments[segments.length - 1];
    if (last && last.voice_id === cur) last.text += ' ' + t;
    else segments.push({ text: t, voice_id: cur });
  }
  // Only worth the multi pipeline when a second voice actually appears.
  multi = segments.length > 0 && segments.some(s => s.voice_id !== fallback);
}
return [{ json: { voice_id: voice, multi, segments } }];

const j = $input.first().json;
const s = (j.status || '').toLowerCase();
if (s === 'error') throw new Error('multi-voice TTS failed: ' + (j.error || 'unknown'));
// Per scene in static data (reset by Sort & Cap each pass) — $runIndex
// would count every scene's polls together, and a pass covers the film.
const sd = $getWorkflowStaticData('global');
sd.multiPolls = sd.multiPolls || {};
const sceneId = $('AB Current Scene').first().json.id;
sd.multiPolls[sceneId] = (sd.multiPolls[sceneId] || 0) + 1;
if (sd.multiPolls[sceneId] > 40) throw new Error('multi-voice TTS timed out after ' + sd.multiPolls[sceneId] + ' polls on scene ' + sceneId + '. Last status: ' + s);
return [{ json: j }];

// Context for the auto-rewrite: the scene, the prompt that was ACTUALLY
// sent, and WHY the image was refused.
//
// Images are generated ON Google Flow (since 2026-09-02), so a refusal is
// Flow's own content filter at GENERATION time — no image was made. The
// upload-time refusals this chain was first built for (MINOR / prominent
// people at Upload Asset To Flow) can now only come from the producer's
// reference photo, which is uploaded once per pass and never lands here.
// Either way the cure is the same: rewrite the prompt, never resubmit the
// refused text. The scene id and note are read from Loop Images rather
// than from the error, which is what lets one chain serve every entry.
//
// The rewrite is retried IN PLACE (Apply Rewritten Prompt → IMG Reload
// Scene → Needs Image?), so this node runs once per attempt for the same
// scene. Attempts are counted per scene per pass in static data (Sort & Cap
// resets sd.imgRewrites); after MAX the scene is handed to a human.
const scene = $('Loop Images').first().json || {};
const f = scene.fields || {};
const errText = JSON.stringify($json).slice(0, 1500);
const service = 'Google Flow';
let reason = service + ' content policy';
if (errText.includes('MINOR')) reason = 'the image appears to contain a child (Flow refuses images with minors)';
else if (errText.includes('PROMINENT') || errText.includes('FACE')) reason = 'the image appears to contain a recognizable real person';
// After an in-place rewrite the Loop Images item still holds the ORIGINAL
// text; the prompt that was sent is Build Image Request's latest run.
let prompt = '';
try { prompt = String($('Build Image Request').first().json.rawPrompt || ''); } catch (e) {}
if (!prompt) prompt = String(f['Imagine First Frame'] || '');
const note = String(f['Observații Scenă'] || '');
const sd = $getWorkflowStaticData('global');
sd.imgRewrites = sd.imgRewrites || {};
const n = (sd.imgRewrites[scene.id] || 0) + 1;
sd.imgRewrites[scene.id] = n;
const MAX = 4;
// A scene that arrives already carrying a refusal note from an earlier pass
// starts one rung further up the escalation ladder.
const attempt = n + (/AUTO-REWRITE|REJECTED/.test(note) ? 1 : 0);
console.log('Image refused for ' + scene.id + ' by ' + service + ' (attempt ' + n + '/' + MAX + ')');
return [{ json: {
  sceneId: scene.id,
  prompt,
  note,
  service,
  reason,
  attempt,
  giveUp: n > MAX,
} }];

