Original prompt:
' + $('VP Prep').first().json.prompt } ] } }}

parameters.jsCode:
// 'Sort & Cap Scenes' runs at most CAP (8) scenes per pass, so a project
// with more approved scenes than that needs several passes. The batch used
// to walk straight from the last approved clip to the final-settings gate,
// which left the tail ungenerated AND kept the execution alive — hiding the
// site's own "Start the next batch" button, whose whole condition is that
// nothing is running. The producer's only way through was Pause + Resume.
//
// So the batch asks for itself: any approved scene still without a clip —
// or owed a video regeneration — means another pass is owed. Same rule as
// `pending` in Sort & Cap Scenes; keep the two together.
const recs = $input.all();
const remaining = recs.filter((r) => {
  const f = r.json.fields || {};
  return !String(f['Scene Final URL'] || '').startsWith('http') || f['Regenerează Video'] === true;
}).length;
// 12 passes = 96 scenes, far past anything real. A scene that can never
// finish (permanent content refusal) must not spin the loop forever — it
// falls through to the gate and the producer sees it unfinished.
const MAX_PASSES = 12;
const more = remaining > 0 && $runIndex + 1 < MAX_PASSES;
if (remaining > 0 && !more) console.log('Batch loop: giving up after ' + ($runIndex + 1) + ' passes with ' + remaining + ' scene(s) still unfinished.');
else console.log('Batch pass ' + ($runIndex + 1) + ' done; ' + remaining + ' scene(s) still to generate.');
return [{ json: { remaining, more, pass: $runIndex + 1 } }];

// The image loop must NOT consume Loop Audio's done output directly: items
// that skipped synthesis re-enter that loop carrying the PROJECT record
// (Needs Voice? -> AB Current Scene -> AB Load Project -> AB No Speech?),
// and one of those reaching Build Image Request kills the whole batch with
// 'Scene ... has no image prompt.' Every stage re-enters from a clean list
// for exactly this reason.
//
// Sort & Cap's own items are replayed verbatim: same records, same
// pending-first order (the n-1 image chain and the regen's recs[i-1] both
// assume that order), and the audio stage between them writes only voice
// fields, so the image-field snapshot is exactly as fresh as it was when
// the image loop read Sort & Cap directly.
return $('Sort & Cap Scenes').all().map(r => ({ json: r.json }));

// Submit Video failed after its own three quick retries. That is usually
// the Flow account being throttled — 'captcha_quality:
// PUBLIC_ERROR_UNUSUAL_ACTIVITY after 5 attempts' killed the whole Vegas
// batch at 8981 — and the cure is time, not a fourth attempt one second
// later. Hold a minute and try again, at most MAX times per scene per run;
// then die with the last reason, exactly as before. The Wait is 60s ON
// PURPOSE: under 65s n8n keeps the execution in memory, so this counter
// (static data) survives; a longer Wait suspends the run to the database
// and the count would not.
// (Sort & Cap Scenes resets the counters at the start of every pass.)
const sd = $getWorkflowStaticData('global');
sd.submitCooldowns = sd.submitCooldowns || {};
const key = $('Current Scene').first().json.id;
const n = (sd.submitCooldowns[key] || 0) + 1;
sd.submitCooldowns[key] = n;
const MAX = 20;
const j = $input.first().json || {};
const last = String((j.error && (j.error.message || j.error.description)) || j.message || JSON.stringify(j)).slice(0, 300);
if (n > MAX) throw new Error('Submit Video kept failing after ' + MAX + ' cooldowns of 60s — last reason: ' + last);
console.log('Submit Video failed (' + n + '/' + MAX + '), cooling down 60s: ' + last);
return [{ json: { cooldown: n, lastError: last } }];

// Same cooldown as 'Submit Cooldown Guard', for the regeneration submit
// inside the video gate. Re-feeds the regen payload, exactly as 'Regen
// Resubmit Guard' does, because Submit Video Regen reads $json.
const sd = $getWorkflowStaticData('global');
sd.submitCooldowns = sd.submitCooldowns || {};
const payload = $('Prep Video Regen').first().json;
const key = 'regen:' + payload.id;
const n = (sd.submitCooldowns[key] || 0) + 1;
sd.submitCooldowns[key] = n;
const MAX = 20;
const j = $input.first().json || {};
const last = String((j.error && (j.error.message || j.error.description)) || j.message || JSON.stringify(j)).slice(0, 300);
if (n > MAX) throw new Error('Submit Video Regen kept failing after ' + MAX + ' cooldowns of 60s — last reason: ' + last);
console.log('Submit Video Regen failed (' + n + '/' + MAX + '), cooling down 60s: ' + last);
return [{ json: payload }];

// Generate Scene Image failed (its quick retries are OFF on purpose: a burst
// of identical requests is exactly what trips Flow's unusual-activity
// filter). Sort the failure into the three things that can be done about it:
//  - a content refusal  -> the rewrite-in-place ladder (Prep Flow Reject);
//  - out of credits (402) -> fatal, the run dies loudly, never loops;
//  - everything else (429, 503, captcha_quality, timeouts, 5xx)
//                        -> IMG Cooldown Guard, i.e. time, then the same request.
const j = $input.first().json || {};
const text = JSON.stringify(j).slice(0, 2000);
const status = Number((j.error && (j.error.httpCode || j.error.statusCode)) || j.httpCode || j.statusCode || (/"httpCode":"?(\d{3})/.exec(text) || [])[1] || 0);
if (status === 402 || /insufficient credits|out of credits|"402"/i.test(text)) throw new Error('Google Flow: out of credits — ' + text.slice(0, 300));
const throttled = /captcha_quality|UNUSUAL_ACTIVITY|TOO_MUCH_TRAFFIC/i.test(text);
const refusal = !throttled && /PROMINENT|MINOR|FILTER|SAFETY|content policy|content_policy|blocked/i.test(text);
return [{ json: Object.assign({}, j, { imgRefusal: refusal, imgThrottled: throttled, imgStatus: status }) }];

// Flow image generation failed for a reason that is not a content refusal:
// 429, 503, a captcha_quality throttle, a timeout. The cure is TIME, not a
// fourth attempt one second later. Hold a minute and try again, at most
// MAX times per scene per pass; then die with the last reason, exactly as
// Submit Cooldown Guard does for videos. The Wait is 60s ON PURPOSE: under
// 65s n8n keeps the execution in memory and this counter (static data)
// survives; a longer Wait suspends the run to the database and the count
// would not. Sort & Cap Scenes resets the counters at the start of every pass.
const sd = $getWorkflowStaticData('global');
sd.imgCooldowns = sd.imgCooldowns || {};
const sceneId = $('Build Image Request').first().json.sceneId;
const key = sceneId;
const n = (sd.imgCooldowns[key] || 0) + 1;
sd.imgCooldowns[key] = n;
const MAX = 20;
const j = $input.first().json || {};
const last = String(j.lastError || (j.error && (j.error.message || j.error.description)) || j.message || JSON.stringify(j)).slice(0, 300);
if (n > MAX) throw new Error('Flow image generation kept failing after ' + MAX + ' cooldowns of 60s — last reason: ' + last);
// A throttle needs TIME, not attempts: hold five cooldowns (5 min) per try.
const throttled = !!j.imgThrottled;
const holds = throttled ? 5 : 1;
const retryNow = n % holds === 0;
console.log('Flow image ' + sceneId + ' failed (' + n + '/' + MAX + '), cooling down 60s' + (retryNow ? ', then retrying' : '') + ': ' + last);
return [{ json: { cooldown: n, retryNow: retryNow, imgThrottled: throttled, lastError: last } }];

// One reference portrait per character, made once per film.
//
// The n-1 chain carries a face from scene to scene, and it was measured
// working — the same man survives 71 scenes of the Boyd film. What it cannot
// do is carry a CAST: the reference is whoever was in the last frame, so on a
// two-hander every scene tells the model to take one man's identity from a
// picture of the other, and a character who appears every fifth scene has no
// anchor at all. A sheet gives each character one fixed appearance that does
// not have to travel.
//
// Free on this plan (Flow image generation spends no Google AI credits on the
// Ultra account), one call per character, once per film: `castRefs` is stored
// on the project, so later passes find it and this node emits nothing.
const proj = $('IMG Load Project').first().json;
const f = proj.fields || {};
let opts = {};
try { opts = JSON.parse(f['Editing Options'] || '{}') || {}; } catch (e) { opts = {}; }
const refs = (opts.castRefs && typeof opts.castRefs === 'object') ? opts.castRefs : {};
let bible = {};
try { bible = JSON.parse(f['Story Bible'] || '{}') || {}; } catch (e) { bible = {}; }
const chars = Array.isArray(bible.characters) ? bible.characters : [];
const rb = $('Receive Batch Input').first().json;
const aspect = rb.Aspect_Ratio === '9:16' ? '9:16' : '16:9';
const MODEL = 'nano-banana-2';

const work = [];
for (const c of chars) {
  const name = String((c || {}).name || '').trim();
  const desc = String((c || {}).visual_description || '').trim();
  if (!name || !desc) continue;
  if (refs[name]) continue;
  // Four is already more principals than a short film can hold; past that the
  // sheets cost Flow calls for people the script mentions once.
  if (work.length >= 4) break;
  work.push({
    name: name,
    requestBody: {
      email: rb.Flow_Email || 'fermafabiz@gmail.com',
      model: MODEL,
      prompt:
        'Character reference portrait of ONE person, centred, front three-quarter view, plain neutral studio backdrop, even soft lighting, no props, no text, no collage: ' +
        desc +
        ' If the description offers alternatives for different eras or scenes, use the FIRST one only — one person, one outfit, one age. Photorealistic, natural skin texture, sharp focus.',
      aspectRatio: aspect,
      count: 1,
      captchaRetry: 1,
    },
  });
}
// NEVER return zero items: everything downstream of this node is the rest of
// the batch, and an empty output would end the pass silently. The flag is what
// Cast Sheet? routes on.
if (!work.length) return [{ json: { skip: true, castRefs: refs } }];
return work.map((w) => ({ json: w }));

// Pair each generated sheet with the character it was made for, and hand the
// whole map on as ONE item.
//
// The HTTP node is onError: continueRegularOutput, so a refused or failed
// portrait arrives here as an item without media rather than as a dead batch —
// that character simply has no sheet and falls back to the n-1 chain, which is
// exactly today's behaviour. Order is 1:1 with Cast Sheet Prep's items.
const prep = $('Cast Sheet Prep').all();
const outs = $input.all();
const made = {};
const failed = [];
outs.forEach((it, i) => {
  const name = String((((prep[i] || {}).json) || {}).name || '');
  let id = '';
  try {
    id = String(((((it.json || {}).media || [])[0] || {}).image || {}).generatedImage?.mediaGenerationId || '');
  } catch (e) { id = ''; }
  if (name && id) made[name] = id;
  else if (name) failed.push(name);
});
for (const n of failed) console.log('CAST SHEET FAILED: ' + n + ' — this character falls back to the n-1 chain');
console.log('CAST SHEETS: ' + (Object.keys(made).join(', ') || 'none'));

// Merged with whatever the project already had, because `||` on jsonb replaces
// the whole castRefs key rather than merging into it.
let existing = {};
try {
  existing = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}').castRefs || {};
} catch (e) { existing = {}; }
return [{ json: { castRefs: Object.assign({}, existing, made), made: Object.keys(made).length } }];
